// Normaliza parámetros del agente. Acepta brand, model, year.
const raw = $input.first().json || {};

// Detectar si los parámetros están dentro de un objeto 'query'
const data = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;
const brand = (data.brand || raw.brand || '').trim();
const model = (data.model || raw.model || '').trim();
const year  = parseInt(data.year || raw.year, 10) || null;

// Estrategia: match exacto primero, luego fallback con rango ±3 años
return [{ json: { brand, model, year, year_lo: year ? year - 3 : null, year_hi: year ? year + 3 : null } }];

const rows = $input.all().map(i => i.json);
const input = $('Normalize Input').first().json;

if (!rows.length) {
  return [{ json: {
    found: false,
    message: `No se encontró fitment exacto para ${input.brand} ${input.model} ${input.year || ''}. Sugerencia: usar search_attributes_jsonb o search_products_by_brand.`,
    query: input
  } }];
}

const matchType = rows[0].match_type;
return [{ json: {
  found: true,
  match_type: matchType,
  count: rows.length,
  results: rows.map(r => ({
    vehicle: `${r.vehicle_brand} ${r.vehicle_model} (${r.year_start}-${r.year_end || 'now'})`,
    sku: r.store_product_code || r.fitment_sku,
    product: r.store_title || r.product_name,
    category: r.product_category,
    price: r.price_amount ? `${r.price_amount} ${r.currency || 'USD'}` : 'consultar',
    stock: r.stock_status || 'unknown',
    image_url: r.image_url || null,
    promo: r.promo_text || null,
    notes: r.fitment_notes
  }))
} }];
